import assert from "node:assert/strict";
import { createRequire } from "node:module";
import { readFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { test } from "node:test";
import { fileURLToPath } from "node:url";

const root = join(dirname(fileURLToPath(import.meta.url)), "..");
const P = await import(join(root, "src/lib/pets/window-play.ts"));
const require = createRequire(import.meta.url);
const Overlay = require(join(root, "../desktop/renderer/window-play.js"));

const livingSrc = readFileSync(join(root, "src/components/desk/living-pet.tsx"), "utf8");
const demoSrc = readFileSync(join(root, "src/components/desk/demo-stage.tsx"), "utf8");
const rosterSrc = readFileSync(join(root, "src/lib/pets/roster.ts"), "utf8");
const guideSrc = readFileSync(join(root, "src/lib/pets/house-guide.ts"), "utf8");

const WORK = { width: 1400, height: 800, floorLift: 0 };
const WIN = { id: "hw", x: 360, y: 80, width: 640, height: 420 };

test("Rui cling-dive is shared; Arc ridge is shared; Volt coil is shared; Trace path is shared; Flux field is shared; Miso sits a ledge; Pip watches from the floor; Thimble thumps then vanishes; Clip stashes in a drawer; Whee wheeks at a window; Ink basks on a rail; Coin circles a bowl; Echo perches a shade; Rue scents a jamb; Peck bows a pane; Quill hooks a jamb; Wick threads a gap; Burr balls at a pane foot; Floss dusts a meeting rail; Bloom walks a tank wall; Keel tosses fruit from a cornice; Sol flattens on a sun-warmed pane; Vesper drapes a lintel; Ember kindles the ash; Nori buns in a sash well; Saffron writes a sash canyon; Bandit inspects a jamb as a ruler; Jade saddles a casement stay; Bluff flips dead on a stool; Sash patrols a moss-cup; Lula loops an apron; Coral mosaics a muntin; Blush stones a sill horn; Atlas charts a transom; Cup lids a sash latch; Sepia flushes a window light; Chamber rises a jamb as stacked rooms; Pulse chimes a pane as a glass of water; Ochre reefs a pane as a damp blotter; Tenant knobs a sash lift as a vacant shell; Ledger plows a stool as a sand tray; Anchor hitches a parting bead as a pencil", () => {
  assert.equal(P.playFor("red_panda"), Overlay.playFor("red_panda"));
  assert.equal(P.playFor("cyber_dragon"), "ridge");
  assert.equal(P.playFor("cyber_dragon"), Overlay.playFor("cyber_dragon"));
  assert.equal(P.playFor("volt_dragon"), "coil");
  assert.equal(P.playFor("volt_dragon"), Overlay.playFor("volt_dragon"));
  assert.equal(P.playFor("trace_dragon"), "path");
  assert.equal(P.playFor("trace_dragon"), Overlay.playFor("trace_dragon"));
  assert.equal(P.playFor("flux_dragon"), "field");
  assert.equal(P.playFor("flux_dragon"), Overlay.playFor("flux_dragon"));
  assert.equal(P.playFor("spark_dragon"), "crackle");
  assert.equal(P.playFor("spark_dragon"), Overlay.playFor("spark_dragon"));
  assert.equal(P.playFor("ion_dragon"), "charge");
  assert.equal(P.playFor("ion_dragon"), Overlay.playFor("ion_dragon"));
  assert.equal(P.playFor("gauss_dragon"), "orbit");
  assert.equal(P.playFor("gauss_dragon"), Overlay.playFor("gauss_dragon"));
  assert.equal(P.playFor("relay_dragon"), "click");
  assert.equal(P.playFor("relay_dragon"), Overlay.playFor("relay_dragon"));
  assert.equal(P.playFor("fuse_dragon"), "hold");
  assert.equal(P.playFor("fuse_dragon"), Overlay.playFor("fuse_dragon"));
  assert.equal(P.playFor("ground_dragon"), "earth");
  assert.equal(P.playFor("ground_dragon"), Overlay.playFor("ground_dragon"));
  assert.equal(P.playFor("cat"), "ledge");
  assert.equal(P.playFor("cat"), Overlay.playFor("cat"));
  assert.equal(P.playFor("dog"), "watch");
  assert.equal(P.playFor("dog"), Overlay.playFor("dog"));
  assert.equal(P.playFor("rabbit"), "thump");
  assert.equal(P.playFor("rabbit"), Overlay.playFor("rabbit"));
  assert.equal(P.playFor("hamster"), "stash");
  assert.equal(P.playFor("hamster"), Overlay.playFor("hamster"));
  assert.equal(P.playFor("guinea_pig"), "wheek");
  assert.equal(P.playFor("guinea_pig"), Overlay.playFor("guinea_pig"));
  assert.equal(P.playFor("turtle"), "bask");
  assert.equal(P.playFor("turtle"), Overlay.playFor("turtle"));
  assert.equal(P.playFor("goldfish"), "circle");
  assert.equal(P.playFor("goldfish"), Overlay.playFor("goldfish"));
  assert.equal(P.playFor("budgie"), "perch");
  assert.equal(P.playFor("budgie"), Overlay.playFor("budgie"));
  assert.equal(P.playFor("fox"), "scent");
  assert.equal(P.playFor("fox"), Overlay.playFor("fox"));
  assert.equal(P.playFor("penguin"), "bow");
  assert.equal(P.playFor("penguin"), Overlay.playFor("penguin"));
  assert.equal(P.playFor("parrot"), "hook");
  assert.equal(P.playFor("parrot"), Overlay.playFor("parrot"));
  assert.equal(P.playFor("ferret"), "thread");
  assert.equal(P.playFor("ferret"), Overlay.playFor("ferret"));
  assert.equal(P.playFor("hedgehog"), "ball");
  assert.equal(P.playFor("hedgehog"), Overlay.playFor("hedgehog"));
  assert.equal(P.playFor("chinchilla"), "dust");
  assert.equal(P.playFor("chinchilla"), Overlay.playFor("chinchilla"));
  assert.equal(P.playFor("axolotl"), "wall");
  assert.equal(P.playFor("axolotl"), Overlay.playFor("axolotl"));
  assert.equal(P.playFor("toucan"), "toss");
  assert.equal(P.playFor("toucan"), Overlay.playFor("toucan"));
  assert.equal(P.playFor("iguana"), "flatten");
  assert.equal(P.playFor("iguana"), Overlay.playFor("iguana"));
  assert.equal(P.playFor("dragon"), "drape");
  assert.equal(P.playFor("dragon"), Overlay.playFor("dragon"));
  assert.equal(P.playFor("phoenix"), "kindle");
  assert.equal(P.playFor("phoenix"), Overlay.playFor("phoenix"));
  assert.equal(P.playFor("ball_python"), "bun");
  assert.equal(P.playFor("ball_python"), Overlay.playFor("ball_python"));
  assert.equal(P.playFor("corn_snake"), "write");
  assert.equal(P.playFor("corn_snake"), Overlay.playFor("corn_snake"));
  assert.equal(P.playFor("kingsnake"), "inspect");
  assert.equal(P.playFor("kingsnake"), Overlay.playFor("kingsnake"));
  assert.equal(P.playFor("green_tree_python"), "saddle");
  assert.equal(P.playFor("green_tree_python"), Overlay.playFor("green_tree_python"));
  assert.equal(P.playFor("hognose"), "flip");
  assert.equal(P.playFor("hognose"), Overlay.playFor("hognose"));
  assert.equal(P.playFor("garter"), "patrol");
  assert.equal(P.playFor("garter"), Overlay.playFor("garter"));
  assert.equal(P.playFor("boa"), "loop");
  assert.equal(P.playFor("boa"), Overlay.playFor("boa"));
  assert.equal(P.playFor("milk_snake"), "mosaic");
  assert.equal(P.playFor("milk_snake"), Overlay.playFor("milk_snake"));
  assert.equal(P.playFor("gecko"), "sill");
  assert.equal(P.playFor("gecko"), Overlay.playFor("gecko"));
  assert.equal(P.playFor("rosy_boa"), "stone");
  assert.equal(P.playFor("rosy_boa"), Overlay.playFor("rosy_boa"));
  assert.equal(P.playFor("carpet_python"), "chart");
  assert.equal(P.playFor("carpet_python"), Overlay.playFor("carpet_python"));
  assert.equal(P.playFor("octopus"), "lid");
  assert.equal(P.playFor("octopus"), Overlay.playFor("octopus"));
  assert.equal(P.playFor("cuttlefish"), "flush");
  assert.equal(P.playFor("cuttlefish"), Overlay.playFor("cuttlefish"));
  assert.equal(P.playFor("nautilus"), "rise");
  assert.equal(P.playFor("nautilus"), Overlay.playFor("nautilus"));
  assert.equal(P.playFor("moon_jelly"), "chime");
  assert.equal(P.playFor("moon_jelly"), Overlay.playFor("moon_jelly"));
  assert.equal(P.playFor("sea_star"), "reef");
  assert.equal(P.playFor("sea_star"), Overlay.playFor("sea_star"));
  assert.equal(P.playFor("hermit_crab"), "knob");
  assert.equal(P.playFor("hermit_crab"), Overlay.playFor("hermit_crab"));
  assert.equal(P.playFor("horseshoe_crab"), "plow");
  assert.equal(P.playFor("horseshoe_crab"), Overlay.playFor("horseshoe_crab"));
  assert.equal(P.playFor("seahorse"), "hitch");
  assert.equal(P.playFor("seahorse"), Overlay.playFor("seahorse"));
  assert.equal(P.canStart({ asleep: true, cmd: "idle" }), false);
  const spin = P.divePath(0.5, { x: 400, lift: 200, side: "right" }, { x: 500, lift: 0 }, "spin");
  const desk = Overlay.divePath(0.5, { x: 400, lift: 200, side: "right" }, { x: 500, lift: 0 }, "spin");
  assert.equal(spin.rot, desk.rot);
  assert.ok(spin.rot > 0);
  const webRidge = P.ridgePoint(WIN, 0.5, 176, WORK);
  const deskRidge = Overlay.ridgePoint(WIN, 0.5, 176, WORK);
  assert.equal(webRidge.lift, deskRidge.lift);
  const webCoil = P.coilPoint(WIN, "left", 176, WORK);
  const deskCoil = Overlay.coilPoint(WIN, "left", 176, WORK);
  assert.equal(webCoil.lift, deskCoil.lift);
  assert.equal(webCoil.x, deskCoil.x);
  const webPath = P.pathPoint(WIN, 0.5, 176, WORK, "left");
  const deskPath = Overlay.pathPoint(WIN, 0.5, 176, WORK, "left");
  assert.equal(webPath.lift, deskPath.lift);
  assert.equal(webPath.x, deskPath.x);
  const webField = P.fieldPoint(WIN, 176, WORK);
  const deskField = Overlay.fieldPoint(WIN, 176, WORK);
  assert.equal(webField.lift, deskField.lift);
  assert.equal(webField.x, deskField.x);
  const webCharge = P.chargePoint(WIN, "tl", 176, WORK);
  const deskCharge = Overlay.chargePoint(WIN, "tl", 176, WORK);
  assert.equal(webCharge.lift, deskCharge.lift);
  assert.equal(webCharge.x, deskCharge.x);
  const webClick = P.clickPoint(WIN, "left", 176, WORK);
  const deskClick = Overlay.clickPoint(WIN, "left", 176, WORK);
  assert.equal(webClick.lift, deskClick.lift);
  assert.equal(webClick.x, deskClick.x);
  const webHold = P.holdPoint(WIN, "jamb", "left", 176, WORK);
  const deskHold = Overlay.holdPoint(WIN, "jamb", "left", 176, WORK);
  assert.equal(webHold.lift, deskHold.lift);
  assert.equal(webHold.x, deskHold.x);
  const webEarth = P.earthPoint(WIN, 176, WORK);
  const deskEarth = Overlay.earthPoint(WIN, 176, WORK);
  assert.equal(webEarth.lift, deskEarth.lift);
  assert.equal(webEarth.x, deskEarth.x);
  const webLedge = P.ledgePoint(WIN, 176, WORK);
  const deskLedge = Overlay.ledgePoint(WIN, 176, WORK);
  assert.equal(webLedge.lift, deskLedge.lift);
  assert.equal(webLedge.x, deskLedge.x);
  const webWatch = P.watchPoint(WIN, 176, WORK);
  const deskWatch = Overlay.watchPoint(WIN, 176, WORK);
  assert.equal(webWatch.lift, deskWatch.lift);
  assert.equal(webWatch.x, deskWatch.x);
  assert.equal(webWatch.lift, 0);
  const webThump = P.thumpPoint(WIN, 176, WORK, "left");
  const deskThump = Overlay.thumpPoint(WIN, 176, WORK, "left");
  assert.equal(webThump.lift, deskThump.lift);
  assert.equal(webThump.x, deskThump.x);
  assert.equal(webThump.lift, 0);
  const webStash = P.stashPoint(WIN, "left", 176, WORK);
  const deskStash = Overlay.stashPoint(WIN, "left", 176, WORK);
  assert.equal(webStash.lift, deskStash.lift);
  assert.equal(webStash.x, deskStash.x);
  assert.ok(webStash.lift > 16);
  const webWheek = P.wheekPoint(WIN, 176, WORK);
  const deskWheek = Overlay.wheekPoint(WIN, 176, WORK);
  assert.equal(webWheek.lift, deskWheek.lift);
  assert.equal(webWheek.x, deskWheek.x);
  assert.equal(webWheek.lift, 0);
  const webBask = P.baskPoint(WIN, 176, WORK);
  const deskBask = Overlay.baskPoint(WIN, 176, WORK);
  assert.equal(webBask.lift, deskBask.lift);
  assert.equal(webBask.x, deskBask.x);
  assert.ok(webBask.lift > webEarth.lift);
  const webCircle = P.circlePoint(WIN, 0, 176, WORK, 1);
  const deskCircle = Overlay.circlePoint(WIN, 0, 176, WORK, 1);
  assert.equal(webCircle.lift, deskCircle.lift);
  assert.equal(webCircle.x, deskCircle.x);
  assert.ok(webCircle.x > WIN.x && webCircle.x + 176 < WIN.x + WIN.width);
  const webPerch = P.perchPoint(WIN, "left", 176, WORK);
  const deskPerch = Overlay.perchPoint(WIN, "left", 176, WORK);
  assert.equal(webPerch.lift, deskPerch.lift);
  assert.equal(webPerch.x, deskPerch.x);
  assert.ok(webPerch.lift > 16);
  const webScent = P.scentPoint(WIN, "left", 176, WORK);
  const deskScent = Overlay.scentPoint(WIN, "left", 176, WORK);
  assert.equal(webScent.lift, deskScent.lift);
  assert.equal(webScent.x, deskScent.x);
  assert.equal(webScent.lift, 0);
  const webBow = P.bowPoint(WIN, 176, WORK);
  const deskBow = Overlay.bowPoint(WIN, 176, WORK);
  assert.equal(webBow.lift, deskBow.lift);
  assert.equal(webBow.x, deskBow.x);
  assert.ok(webBow.lift > 16);
  const webHook = P.hookPoint(WIN, "left", 1, 176, WORK);
  const deskHook = Overlay.hookPoint(WIN, "left", 1, 176, WORK);
  assert.equal(webHook.lift, deskHook.lift);
  assert.equal(webHook.x, deskHook.x);
  assert.ok(webHook.lift > 16);
  const webHookStart = P.hookPoint(WIN, "left", 0, 176, WORK);
  const deskHookStart = Overlay.hookPoint(WIN, "left", 0, 176, WORK);
  assert.equal(webHookStart.lift, deskHookStart.lift);
  assert.equal(webHookStart.x, deskHookStart.x);
  assert.ok(webHook.lift > webHookStart.lift + 40);
  const webThread = P.threadPoint(WIN, 0, 176, WORK);
  const deskThread = Overlay.threadPoint(WIN, 0, 176, WORK);
  assert.equal(webThread.lift, deskThread.lift);
  assert.equal(webThread.x, deskThread.x);
  const webThreadEnd = P.threadPoint(WIN, 1, 176, WORK);
  const deskThreadEnd = Overlay.threadPoint(WIN, 1, 176, WORK);
  assert.equal(webThreadEnd.lift, deskThreadEnd.lift);
  assert.equal(webThreadEnd.x, deskThreadEnd.x);
  assert.ok(Math.abs(webThreadEnd.x - webThread.x) > 80);
  assert.ok(webThread.lift > 8);
  const webBall = P.ballPoint(WIN, 176, WORK);
  const deskBall = Overlay.ballPoint(WIN, 176, WORK);
  assert.equal(webBall.lift, deskBall.lift);
  assert.equal(webBall.x, deskBall.x);
  assert.equal(webBall.lift, 0);
  const webDust = P.dustPoint(WIN, 176, WORK);
  const deskDust = Overlay.dustPoint(WIN, 176, WORK);
  assert.equal(webDust.lift, deskDust.lift);
  assert.equal(webDust.x, deskDust.x);
  assert.ok(webDust.lift > 36);
  const webWall = P.wallPoint(WIN, 0, "left", 176, WORK);
  const deskWall = Overlay.wallPoint(WIN, 0, "left", 176, WORK);
  assert.equal(webWall.lift, deskWall.lift);
  assert.equal(webWall.x, deskWall.x);
  const webWallEnd = P.wallPoint(WIN, 1, "left", 176, WORK);
  const deskWallEnd = Overlay.wallPoint(WIN, 1, "left", 176, WORK);
  assert.equal(webWallEnd.lift, deskWallEnd.lift);
  assert.equal(webWallEnd.x, deskWallEnd.x);
  assert.ok(webWallEnd.lift > webWall.lift + 40, "she walks up the pane");
  const webToss = P.tossPoint(WIN, "left", 176, WORK);
  const deskToss = Overlay.tossPoint(WIN, "left", 176, WORK);
  assert.equal(webToss.lift, deskToss.lift);
  assert.equal(webToss.x, deskToss.x);
  assert.ok(webToss.lift > 36);
  const webFlatten = P.flattenPoint(WIN, 176, WORK);
  const deskFlatten = Overlay.flattenPoint(WIN, 176, WORK);
  assert.equal(webFlatten.lift, deskFlatten.lift);
  assert.equal(webFlatten.x, deskFlatten.x);
  assert.ok(webFlatten.lift > 36);
  const webDrape = P.drapePoint(WIN, "left", 176, WORK);
  const deskDrape = Overlay.drapePoint(WIN, "left", 176, WORK);
  assert.equal(webDrape.lift, deskDrape.lift);
  assert.equal(webDrape.x, deskDrape.x);
  assert.ok(webDrape.lift > 36);
  const webKindle = P.kindlePoint(WIN, 176, WORK);
  const deskKindle = Overlay.kindlePoint(WIN, 176, WORK);
  assert.equal(webKindle.lift, deskKindle.lift);
  assert.equal(webKindle.x, deskKindle.x);
  assert.ok(webKindle.lift > 36);
  const webBun = P.bunPoint(WIN, 176, WORK);
  const deskBun = Overlay.bunPoint(WIN, 176, WORK);
  assert.equal(webBun.lift, deskBun.lift);
  assert.equal(webBun.x, deskBun.x);
  assert.ok(webBun.lift > 36);
  const webWrite = P.writePoint(WIN, 0, 176, WORK);
  const deskWrite = Overlay.writePoint(WIN, 0, 176, WORK);
  assert.equal(webWrite.lift, deskWrite.lift);
  assert.equal(webWrite.x, deskWrite.x);
  const webWriteEnd = P.writePoint(WIN, 1, 176, WORK);
  const deskWriteEnd = Overlay.writePoint(WIN, 1, 176, WORK);
  assert.equal(webWriteEnd.lift, deskWriteEnd.lift);
  assert.equal(webWriteEnd.x, deskWriteEnd.x);
  assert.ok(Math.abs(webWriteEnd.x - webWrite.x) > 80);
  assert.ok(webWrite.lift > 16);
  const webInspect = P.inspectPoint(WIN, "left", 0, 176, WORK);
  const deskInspect = Overlay.inspectPoint(WIN, "left", 0, 176, WORK);
  assert.equal(webInspect.lift, deskInspect.lift);
  assert.equal(webInspect.x, deskInspect.x);
  const webInspectEnd = P.inspectPoint(WIN, "left", 1, 176, WORK);
  const deskInspectEnd = Overlay.inspectPoint(WIN, "left", 1, 176, WORK);
  assert.equal(webInspectEnd.lift, deskInspectEnd.lift);
  assert.equal(webInspectEnd.x, deskInspectEnd.x);
  assert.ok(Math.abs(webInspectEnd.x - webInspect.x) < 2);
  assert.ok(webInspectEnd.lift - webInspect.lift > 80);
  const webSaddle = P.saddlePoint(WIN, "left", 176, WORK);
  const deskSaddle = Overlay.saddlePoint(WIN, "left", 176, WORK);
  assert.equal(webSaddle.lift, deskSaddle.lift);
  assert.equal(webSaddle.x, deskSaddle.x);
  assert.ok(webSaddle.lift > 36);
  assert.ok(Math.abs(webSaddle.lift - webDrape.lift) > 40, "not Vesper's lintel");
  const webFlip = P.flipPoint(WIN, 176, WORK);
  const deskFlip = Overlay.flipPoint(WIN, 176, WORK);
  assert.equal(webFlip.lift, deskFlip.lift);
  assert.equal(webFlip.x, deskFlip.x);
  assert.ok(webFlip.lift > 16, "the stool is a stage, not the floor");
  assert.ok(Math.abs(webFlip.lift - webSaddle.lift) > 40, "not Jade's stay");
  const webPatrol = P.patrolPoint(WIN, 0, 176, WORK);
  const deskPatrol = Overlay.patrolPoint(WIN, 0, 176, WORK);
  assert.equal(webPatrol.lift, deskPatrol.lift);
  assert.equal(webPatrol.x, deskPatrol.x);
  const webPatrolEnd = P.patrolPoint(WIN, 1, 176, WORK);
  const deskPatrolEnd = Overlay.patrolPoint(WIN, 1, 176, WORK);
  assert.equal(webPatrolEnd.lift, deskPatrolEnd.lift);
  assert.equal(webPatrolEnd.x, deskPatrolEnd.x);
  assert.ok(Math.abs(webPatrolEnd.x - webPatrol.x) > 80, "a cup route");
  assert.ok(webPatrol.lift > 16, "the cup is a trough, not the floor");
  assert.ok(Math.abs(webPatrol.x - webFlip.x) > 20 || Math.abs(webPatrol.lift - webFlip.lift) > 16, "not Bluff's stool");
  const webLoop = P.loopPoint(WIN, 176, WORK);
  const deskLoop = Overlay.loopPoint(WIN, 176, WORK);
  assert.equal(webLoop.lift, deskLoop.lift);
  assert.equal(webLoop.x, deskLoop.x);
  assert.ok(webLoop.lift > 14, "the apron is a river bank, not the floor");
  assert.ok(Math.abs(webLoop.x - webFlip.x) > 20 || Math.abs(webLoop.lift - webFlip.lift) > 16, "not Bluff's stool");
  assert.ok(Math.abs(webLoop.x - webPatrol.x) > 20 || Math.abs(webLoop.lift - webPatrol.lift) > 16, "not Sash's cup");
  const webMosaic = P.mosaicPoint(WIN, 176, WORK);
  const deskMosaic = Overlay.mosaicPoint(WIN, 176, WORK);
  assert.equal(webMosaic.lift, deskMosaic.lift);
  assert.equal(webMosaic.x, deskMosaic.x);
  assert.ok(webMosaic.lift > 28, "the muntin is a stamp sheet, not the floor");
  assert.ok(Math.abs(webMosaic.x - webLoop.x) > 20 || Math.abs(webMosaic.lift - webLoop.lift) > 16, "not Lula's apron");
  assert.ok(Math.abs(webMosaic.x - webPatrol.x) > 20 || Math.abs(webMosaic.lift - webPatrol.lift) > 16, "not Sash's cup");
  assert.ok(Math.abs(webMosaic.x - webInspect.x) > 20 || Math.abs(webMosaic.lift - webInspect.lift) > 20, "not Bandit's ruler");
  const webStone = P.stonePoint(WIN, "left", 176, WORK);
  const deskStone = Overlay.stonePoint(WIN, "left", 176, WORK);
  assert.equal(webStone.lift, deskStone.lift);
  assert.equal(webStone.x, deskStone.x);
  assert.ok(webStone.lift > 16, "the horn is a desert rock, not the floor");
  assert.ok(Math.abs(webStone.x - webMosaic.x) > 20 || Math.abs(webStone.lift - webMosaic.lift) > 16, "not Coral's muntin");
  assert.ok(Math.abs(webStone.x - webLoop.x) > 20 || Math.abs(webStone.lift - webLoop.lift) > 16, "not Lula's apron");
  const webChart = P.chartPoint(WIN, 0, 176, WORK);
  const deskChart = Overlay.chartPoint(WIN, 0, 176, WORK);
  assert.equal(webChart.lift, deskChart.lift);
  assert.equal(webChart.x, deskChart.x);
  const webChartEnd = P.chartPoint(WIN, 1, 176, WORK);
  const deskChartEnd = Overlay.chartPoint(WIN, 1, 176, WORK);
  assert.equal(webChartEnd.x, deskChartEnd.x);
  assert.ok(webChart.lift > 36, "the transom is a map shelf, not the floor");
  assert.ok(Math.abs(webChartEnd.x - webChart.x) > 80, "a runner of carpet");
  assert.ok(Math.abs(webChart.x - webStone.x) > 20 || Math.abs(webChart.lift - webStone.lift) > 16, "not Blush's horn");
  const webLid = P.lidPoint(WIN, 176, WORK);
  const deskLid = Overlay.lidPoint(WIN, 176, WORK);
  assert.equal(webLid.lift, deskLid.lift);
  assert.equal(webLid.x, deskLid.x);
  assert.ok(webLid.lift > 28, "the latch cup is a hide, not the floor");
  assert.ok(Math.abs(webLid.x - webChart.x) > 20 || Math.abs(webLid.lift - webChart.lift) > 16, "not Atlas's transom");
  assert.ok(Math.abs(webLid.x - webStone.x) > 20 || Math.abs(webLid.lift - webStone.lift) > 16, "not Blush's horn");
  const webFlush = P.flushPoint(WIN, 0, 176, WORK);
  const deskFlush = Overlay.flushPoint(WIN, 0, 176, WORK);
  assert.equal(webFlush.lift, deskFlush.lift);
  assert.equal(webFlush.x, deskFlush.x);
  const webFlushEnd = P.flushPoint(WIN, 1, 176, WORK);
  const deskFlushEnd = Overlay.flushPoint(WIN, 1, 176, WORK);
  assert.equal(webFlushEnd.x, deskFlushEnd.x);
  assert.ok(webFlush.lift > 36, "the light is lamp-ripple weather, not the floor");
  assert.ok(Math.abs(webFlushEnd.x - webFlush.x) > 60, "a W across the pane");
  assert.ok(Math.abs(webFlush.x - webLid.x) > 20 || Math.abs(webFlush.lift - webLid.lift) > 16, "not Cup's latch");
  assert.ok(Math.abs(webFlush.x - webChart.x) > 20 || Math.abs(webFlush.lift - webChart.lift) > 16, "not Atlas's transom");
  const webRise = P.risePoint(WIN, "left", 0, 176, WORK);
  const deskRise = Overlay.risePoint(WIN, "left", 0, 176, WORK);
  assert.equal(webRise.lift, deskRise.lift);
  assert.equal(webRise.x, deskRise.x);
  const webRiseEnd = P.risePoint(WIN, "left", 2, 176, WORK);
  const deskRiseEnd = Overlay.risePoint(WIN, "left", 2, 176, WORK);
  assert.equal(webRiseEnd.x, deskRiseEnd.x);
  assert.equal(webRiseEnd.lift, deskRiseEnd.lift);
  assert.ok(webRise.lift > 36, "the first room is on the jamb, not the floor");
  assert.ok(webRiseEnd.lift - webRise.lift > 80, "stacked nacre rooms");
  assert.equal(webRise.x, webRiseEnd.x, "a column, not a W");
  assert.ok(Math.abs(webRise.x - webFlush.x) > 20 || Math.abs(webRise.lift - webFlush.lift) > 16, "not Sepia's light");
  assert.ok(Math.abs(webRise.x - webLid.x) > 20 || Math.abs(webRise.lift - webLid.lift) > 16, "not Cup's latch");
  const webChime = P.chimePoint(WIN, 0, 176, WORK);
  const deskChime = Overlay.chimePoint(WIN, 0, 176, WORK);
  assert.equal(webChime.lift, deskChime.lift);
  assert.equal(webChime.x, deskChime.x);
  const webChimeBottom = P.chimePoint(WIN, 1, 176, WORK);
  const webChimeLeft = P.chimePoint(WIN, 2, 176, WORK);
  const webChimeRight = P.chimePoint(WIN, 3, 176, WORK);
  const deskChimeRight = Overlay.chimePoint(WIN, 3, 176, WORK);
  assert.equal(webChimeRight.x, deskChimeRight.x);
  assert.equal(webChime.x, webChimeBottom.x, "a vertical pair of moons");
  assert.equal(webChimeLeft.lift, webChimeRight.lift, "a horizontal pair of moons");
  assert.ok(webChime.lift - webChimeBottom.lift > 56, "four moons as a cross");
  assert.ok(webChimeRight.x - webChimeLeft.x > 56, "not a column");
  assert.ok(webChime.lift > 36, "the first moon is on the glass, not the floor");
  assert.ok(Math.abs(webChime.x - webRise.x) > 20 || Math.abs(webChime.lift - webRise.lift) > 16, "not Chamber's jamb");
  assert.ok(Math.abs(webChime.x - webFlush.x) > 20 || Math.abs(webChime.lift - webFlush.lift) > 16, "not Sepia's light");
  assert.ok(Math.abs(webChime.x - webLid.x) > 20 || Math.abs(webChime.lift - webLid.lift) > 16, "not Cup's latch");
  const webReef = P.reefPoint(WIN, 176, WORK);
  const deskReef = Overlay.reefPoint(WIN, 176, WORK);
  assert.equal(webReef.lift, deskReef.lift);
  assert.equal(webReef.x, deskReef.x);
  const webReefArm0 = P.reefArm(WIN, 0, 176, WORK);
  const deskReefArm0 = Overlay.reefArm(WIN, 0, 176, WORK);
  assert.equal(webReefArm0.x, deskReefArm0.x);
  assert.equal(webReefArm0.lift, deskReefArm0.lift);
  assert.ok(webReef.lift > 36, "the blotter is wet glass, not the floor");
  assert.ok(Math.abs(webReef.x - webChime.x) > 20 || Math.abs(webReef.lift - webChime.lift) > 16, "not Pulse's saucer");
  assert.ok(Math.abs(webReef.x - webRise.x) > 20 || Math.abs(webReef.lift - webRise.lift) > 16, "not Chamber's jamb");
  assert.ok(Math.abs(webReef.x - webFlush.x) > 20 || Math.abs(webReef.lift - webFlush.lift) > 16, "not Sepia's light");
  assert.ok(Math.abs(webReef.x - webLid.x) > 20 || Math.abs(webReef.lift - webLid.lift) > 16, "not Cup's latch");
  const webKnob = P.knobPoint(WIN, 176, WORK);
  const deskKnob = Overlay.knobPoint(WIN, 176, WORK);
  assert.equal(webKnob.lift, deskKnob.lift);
  assert.equal(webKnob.x, deskKnob.x);
  assert.ok(webKnob.lift > 28, "the sash lift is a vacant shell, not the floor");
  assert.ok(Math.abs(webKnob.x - webLid.x) > 20 || Math.abs(webKnob.lift - webLid.lift) > 16, "not Cup's latch");
  assert.ok(Math.abs(webKnob.x - webReef.x) > 20 || Math.abs(webKnob.lift - webReef.lift) > 16, "not Ochre's blotter");
  const webPlow = P.plowPoint(WIN, 176, WORK);
  const deskPlow = Overlay.plowPoint(WIN, 176, WORK);
  assert.equal(webPlow.lift, deskPlow.lift);
  assert.equal(webPlow.x, deskPlow.x);
  assert.ok(webPlow.lift > 18, "the stool is a sand tray, not the floor");
  assert.ok(Math.abs(webPlow.x - webKnob.x) > 20 || Math.abs(webPlow.lift - webKnob.lift) > 16, "not Tenant's lift");
  assert.ok(Math.abs(webPlow.x - webReef.x) > 20 || Math.abs(webPlow.lift - webReef.lift) > 16, "not Ochre's blotter");
  const webHitch = P.hitchPoint(WIN, 176, WORK);
  const deskHitch = Overlay.hitchPoint(WIN, 176, WORK);
  assert.equal(webHitch.lift, deskHitch.lift);
  assert.equal(webHitch.x, deskHitch.x);
  assert.ok(webHitch.lift > 36, "the parting bead is a pencil, not the floor");
  assert.ok(Math.abs(webHitch.x - webPlow.x) > 20 || Math.abs(webHitch.lift - webPlow.lift) > 16, "not Ledger's stool");
  assert.ok(Math.abs(webHitch.x - webKnob.x) > 20 || Math.abs(webHitch.lift - webKnob.lift) > 16, "not Tenant's lift");
});

test("the demo room walks the same Rui climb against a drawn window", () => {
  assert.match(demoSrc, /demoWindow/);
  assert.match(livingSrc, /playFor/);
  assert.match(livingSrc, /stepPlay/);
  assert.match(livingSrc, /shouldAbort/);
  assert.match(livingSrc, /asleepRef/);
  const target = P.pickTarget([WIN], 40, "red_panda", WORK, 176, { side: "left", spin: "backflip", diveFrom: "top" });
  let play = P.beginPlay(target, target.approachX);
  const seen = new Set();
  for (let i = 0; i < 400 && play.phase !== "done"; i++) {
    seen.add(play.phase);
    play = P.stepPlay(play, 0.05, { x: play.x, lift: play.lift }, [WIN], WORK, 176, { cmd: "idle" });
  }
  assert.ok(seen.has("cling"));
  assert.ok(seen.has("dive"));
  assert.equal(play.phase, "done");
});

