  const saddle = P.saddlePoint(WIN, "left", 176, WORK);
  const flip = P.flipPoint(WIN, 176, WORK);
  const patrol = P.patrolPoint(WIN, 0, 176, WORK);
  const loop = P.loopPoint(WIN, 176, WORK);
  const mosaic = P.mosaicPoint(WIN, 176, WORK);
