  const hook = P.hookPoint(WIN, "left", 1, 176, WORK);
  const bow = P.bowPoint(WIN, 176, WORK);
  const scent = P.scentPoint(WIN, "left", 176, WORK);
  const perch = P.perchPoint(WIN, "left", 176, WORK);
